#pragma once
#include "common.hpp"
namespace snuw {
inline std::wstring outputName(const std::string& name,const std::wstring& fallback){auto value=wide(name);for(auto& c:value)if(c<32||std::wstring(L"<>:\"/\\|?*").find(c)!=std::wstring::npos)c=L'_';while(!value.empty()&&(value.back()==L'.'||value.back()==L' '))value.pop_back();if(value.empty()||value==L"."||value==L"..")value=fallback;if(value.size()>50)value.resize(50);auto stem=value.substr(0,value.find(L'.'));std::transform(stem.begin(),stem.end(),stem.begin(),::towupper);if(stem==L"CON"||stem==L"PRN"||stem==L"AUX"||stem==L"NUL"||(stem.size()==4&&(stem.substr(0,3)==L"COM"||stem.substr(0,3)==L"LPT")&&stem[3]>=L'1'&&stem[3]<=L'9'))value=L"_"+value;return value;}
inline fs::path outputDirectory(const json& cfg){auto root=fs::path(wide(str(cfg,"output")));auto target=root/outputName(str(cfg,"creator_name"),L"User")/(str(cfg,"content_mode")=="hardcore"?L"Hardcore":L"Standard");auto folder=str(cfg,"folder_name");if(!folder.empty())target/=outputName(folder,L"Folder");return target/outputName(str(cfg,"channel_name"),L"Channel");}
inline fs::path imageMetadataPath(const fs::path& image){for(auto root=image.parent_path();!root.empty()&&root!=root.parent_path();root=root.parent_path()){if(fs::exists(root/L".snuw-output.json")){auto relative=image.lexically_relative(root);std::vector<fs::path> parts;for(auto& p:relative)parts.push_back(p);if(parts.size()>=4){auto target=root/L"_metadata"/parts.front()/parts[parts.size()-2]/image.filename();target.replace_extension(L".json");return target;}break;}}auto path=image;path.replace_extension(L".json");return path;}
}
